#!/usr/bin/env node
// Build the plugin catalog (category and one-line description per plugin) from the Apache APISIX
// docs, for the Plugins tab's picker and card chips.
//
//   node dev/gen-plugin-catalog.mjs [path/to/apisix]    default ~/apiseven-ref/apisix
//
// Reads docs/en/latest/config.json (the docs sidebar: its "Plugins" category, whose innermost
// sub-categories become the catalog's categories, in sidebar order) and the `description:` line of
// each docs/en/latest/plugins/<doc>.md front matter. Writes web/src/plugins/catalog.ts with sorted
// keys, so a regenerated file diffs cleanly. Node 22+, no dependencies.
import { readFileSync, writeFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(process.argv[2] ?? join(homedir(), 'apiseven-ref', 'apisix'));
const DOCS = join(ROOT, 'docs', 'en', 'latest');
const OUT = join(dirname(fileURLToPath(import.meta.url)), '..', 'web', 'src', 'plugins', 'catalog.ts');

// One page documents several plugins: the page id → the plugin names it covers.
const SHARED_PAGES = { serverless: ['serverless-pre-function', 'serverless-post-function'] };

const slug = (label) => label.trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

/** The sidebar's Plugins category. */
function pluginsCategory(config) {
  const stack = [config];
  while (stack.length) {
    const node = stack.pop();
    if (Array.isArray(node)) stack.push(...node);
    else if (node && typeof node === 'object') {
      if (node.type === 'category' && node.label === 'Plugins') return node;
      stack.push(...Object.values(node));
    }
  }
  throw new Error(`no "Plugins" category in ${join(DOCS, 'config.json')}`);
}

/** [category slug, label, page ids] for every category that lists plugin pages itself, in sidebar order. */
function categories(node, out = []) {
  const pages = [];
  for (const item of node.items ?? []) {
    if (typeof item === 'string') {
      if (item.startsWith('plugins/')) pages.push(item.slice('plugins/'.length));
    } else if (item?.type === 'category') {
      // Keep the sidebar order: a category's own pages come before its sub-categories' only when
      // they are listed first, which is how the APISIX sidebar is written.
      if (pages.length) out.push([slug(node.label), node.label, pages.splice(0)]);
      categories(item, out);
    }
  }
  if (pages.length) out.push([slug(node.label), node.label, pages]);
  return out;
}

/** Markdown reduced to plain text: links to their text, no code ticks or emphasis, one line. */
const plain = (md) =>
  md
    .replace(/!?\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/[`*_]{1,2}([^`*_]+)[`*_]{1,2}/g, '$1')
    .replace(/`/g, '')
    .replace(/\s+/g, ' ')
    .trim();

// About 40 pages carry this boilerplate as their front-matter description; their "## Description"
// section says what the plugin does.
const BOILERPLATE = /^This document contains information about/;

/** The front matter's `description:`, else (boilerplate) the first paragraph of "## Description". */
function description(page) {
  const text = readFileSync(join(DOCS, 'plugins', `${page}.md`), 'utf8');
  const front = /^---\n([\s\S]*?)\n---/.exec(text)?.[1] ?? '';
  let value = /^description:\s*(.*)$/m.exec(front)?.[1]?.trim() ?? '';
  if (/^(['"]).*\1$/.test(value)) value = value.slice(1, -1);
  if (BOILERPLATE.test(value) || value === '') {
    const section = /^## Description\s*\n+([^\n]+(?:\n[^\n#<:|`-][^\n]*)*)/m.exec(text)?.[1];
    if (section) value = section;
  }
  return firstSentences(plain(value), 300);
}

/** Whole sentences from the start while they fit in `max` characters (always at least one). */
function firstSentences(text, max) {
  const sentences = text.split(/(?<=[.!?])\s+(?=[A-Z])/);
  let out = sentences[0] ?? '';
  for (const s of sentences.slice(1)) {
    if (out.length + 1 + s.length > max) break;
    out += ` ${s}`;
  }
  return out;
}

const config = JSON.parse(readFileSync(join(DOCS, 'config.json'), 'utf8'));
const groups = categories(pluginsCategory(config));
const order = [];
const catalog = {};
for (const [category, , pages] of groups) {
  if (!order.includes(category)) order.push(category);
  for (const page of pages) {
    const desc = description(page);
    for (const name of SHARED_PAGES[page] ?? [page]) {
      catalog[name] = page === name ? { category, description: desc } : { category, description: desc, doc: page };
    }
  }
}

const entries = Object.keys(catalog)
  .sort()
  .map((name) => `  ${JSON.stringify(name)}: ${JSON.stringify(catalog[name])},`);
const labels = groups.filter(([c], i) => groups.findIndex(([d]) => d === c) === i).map(([c, label]) => `${c}=${label}`);

const file = `// GENERATED by dev/gen-plugin-catalog.mjs — do not edit. Regenerate with
//   node dev/gen-plugin-catalog.mjs [path/to/apisix]   (default ~/apiseven-ref/apisix)
// Categories follow the Plugins section of the APISIX docs sidebar (docs/en/latest/config.json);
// descriptions are the front-matter \`description\` of docs/en/latest/plugins/<doc>.md.
// Descriptions come from the Apache APISIX documentation (Apache License 2.0).
// Sidebar labels: ${labels.join(', ')}.

export interface CatalogEntry {
  /** A category id, in CATEGORIES; its label is i18n \`pl.category.<id>\`. */
  category: string;
  description: string;
  /** The docs page, when it is not named after the plugin (one page covers several plugins). */
  doc?: string;
}

/** Category ids in the docs sidebar's order. */
export const CATEGORIES: readonly string[] = ${JSON.stringify(order)};

export const catalog: Record<string, CatalogEntry> = {
${entries.join('\n')}
};
`;
writeFileSync(OUT, file);
console.log(`${OUT}: ${Object.keys(catalog).length} plugins in ${order.length} categories (${order.join(', ')})`);
